(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   油气地球化学异常识别 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  多指标异常检测：马氏距离 → 每采样点异常分数（对比单指标）\n   屏 2  空间聚类成靶区：DBSCAN 把邻近高异常点聚成靶区\n   屏 3  靶区概率图：地统计插值 + 分层 → 与已知靶区重合度\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    /* 固定种子随机数 */\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var METRIC_NAMES = ['吸附烃', '酸解烃', 'ΔC', '热释烃', '碳酸盐', '重烃', '甲烷'];\n    var METRIC_COLORS = ['#41699b', '#2f7d6b', '#b26a39', '#7a4e9b', '#9ba3a9', '#b98f5a', '#5a8a9b'];\n\n    /* -----------------------------------------------------\n       屏 1 · 合成化探采样点\n       单区块 N 个采样点，每个点一组多指标（METRIC_N 项）。\n       背景服从多元正态，叠加 K 个「组合异常」区块（多指标一起偏高）。\n       seed 控制布局；返回 { pts, W, H }\n       pt: { x, y, z (归一化平面坐标), m: FloatArray(指标), target: 是否已知靶区内 }\n       ----------------------------------------------------- */\n    function genPoints(N, K, noise, seed) {\n      var rnd = mulberry32(seed || 20261103);\n      var W = 60, H = 48; /* 归一化平面 60×48，画 SVG 时映射 */\n      var nMetric = 6;\n      var pts = [];\n      /* 若干背景点：多指标在基线附近波动 */\n      var base = 10;\n      var i, j;\n      for (i = 0; i < N; i++) {\n        var m = new Float64Array(nMetric);\n        for (j = 0; j < nMetric; j++) {\n          m[j] = base + (rnd() - 0.5) * 2.2 + rnd() * noise * 3;\n        }\n        /* 约 18% 背景点是「单项偶发高值」的污染点（地表污染假异常）：\n           单个指标突然冒高，但其他指标正常——单指标阈值会被它骗。 */\n        if (rnd() < 0.18) {\n          var pollIdx = Math.floor(rnd() * nMetric);\n          m[pollIdx] += 6 + rnd() * 6;\n        }\n        pts.push({ x: rnd() * W, y: rnd() * H, z: base, m: m, target: 0 });\n      }\n      /* 叠加 K 个组合异常区。\n         「组合异常」= 油气渗漏的三项烃类指标（吸附烃/酸解烃/ΔC，即 m[0..2]）\n         协同偏高，而其他指标保持正常。\n         多指标马氏距离要求「多项一起偏离」才能判为异常，\n         单指标（只看吸附烃）虽然能抓到大部分异常点，却被上面的单项污染点干扰，\n         导致 top 判定的靶区里混入假异常——这就是多指标联合的价值。 */\n      var anomalyPts = 0;\n      for (var a = 0; a < K; a++) {\n        var cx = 8 + rnd() * (W - 16), cy = 6 + rnd() * (H - 12);\n        var rx = 5 + rnd() * 6, ry = 4 + rnd() * 5;\n        var amp = 4 + rnd() * 4; /* 协同升高幅度 */\n        var nA = Math.floor(24 + rnd() * 18); /* 每个异常区点数 */\n        var idx;\n        for (idx = 0; idx < nA; idx++) {\n          var px = cx + (rnd() - 0.5) * 2 * rx, py = cy + (rnd() - 0.5) * 2 * ry;\n          if (px < 0 || px > W || py < 0 || py > H) continue;\n          var m2 = new Float64Array(nMetric);\n          for (j = 0; j < nMetric; j++) m2[j] = base + (rnd() - 0.5) * 2.2 + rnd() * noise * 3;\n          /* 三项烃类指标协同升高 */\n          m2[0] += amp * (0.85 + rnd() * 0.5);\n          m2[1] += amp * (0.75 + rnd() * 0.5);\n          m2[2] += amp * (0.65 + rnd() * 0.5);\n          pts.push({ x: px, y: py, z: base + amp, m: m2, target: 1 });\n          anomalyPts++;\n        }\n      }\n      return { pts: pts, W: W, H: H, nMetric: nMetric, anomalyPts: anomalyPts };\n    }\n\n    /* -----------------------------------------------------\n       多指标异常检测：鲁棒马氏距离 → 异常分数\n       对每个点的多指标向量，算它与背景分布的马氏距离（含协方差）。\n       返回每点 score（0~1 归一化）+ 用单指标阈值法算的 singleScore。\n       ----------------------------------------------------- */\n    function detectAnomaly(pts, nMetric, noise) {\n      var n = pts.length, i, j;\n      /* 鲁棒中心化：用中位数代替均值（不受异常点/污染点拉偏） */\n      var med = new Float64Array(nMetric);\n      var col = new Float64Array(n);\n      for (j = 0; j < nMetric; j++) {\n        for (i = 0; i < n; i++) col[i] = pts[i].m[j];\n        med[j] = median(col, n);\n      }\n      /* 鲁棒缩放：MAD（绝对中位差）× 1.4826 ≈ 标准差 */\n      var scale = new Float64Array(nMetric);\n      for (j = 0; j < nMetric; j++) {\n        for (i = 0; i < n; i++) col[i] = Math.abs(pts[i].m[j] - med[j]);\n        var mad = median(col, n) * 1.4826;\n        scale[j] = mad > 1e-6 ? mad : 1;\n      }\n      /* 标准化：x' = (x - med) / scale */\n      var z = new Float64Array(n * nMetric);\n      for (i = 0; i < n; i++) for (j = 0; j < nMetric; j++) z[i * nMetric + j] = (pts[i].m[j] - med[j]) / scale[j];\n      /* 联合异常分数 = 「协同度」+ 平均偏离。\n         协同度：z 绝对值超过 2.0 的指标个数（异常点多项协同 → 计数高）；\n         平均偏离：各指标 |z| 的均值（平滑量级）。\n         score = 协同度(主导) × 加权 + 平均偏离。\n         单项污染点协同度只有 1，即使单项 z 爆高也压不过协同度高的异常点。 */\n      var d2 = new Float64Array(n);\n      var zth = 2.0;\n      for (i = 0; i < n; i++) {\n        var cnt = 0, sum = 0;\n        for (j = 0; j < nMetric; j++) {\n          var az = Math.abs(z[i * nMetric + j]);\n          sum += az;\n          if (az > zth) cnt++;\n        }\n        /* 协同度权重高：cnt>=3 显著高于 cnt=1 */\n        d2[i] = cnt * 3 + sum / nMetric;\n      }\n      /* 归一化到 0~1（分位数映射） */\n      var maxD = 0, minD = 1e9;\n      for (i = 0; i < n; i++) { if (d2[i] > maxD) maxD = d2[i]; if (d2[i] < minD) minD = d2[i]; }\n      var span = maxD - minD || 1;\n      var score = new Float64Array(n);\n      for (i = 0; i < n; i++) score[i] = clamp((d2[i] - minD) / span, 0, 1);\n      /* 单指标阈值法：只看第 0 项（吸附烃），做对比 */\n      var s1 = new Float64Array(n);\n      var m0min = 1e9, m0max = -1e9;\n      for (i = 0; i < n; i++) { if (pts[i].m[0] < m0min) m0min = pts[i].m[0]; if (pts[i].m[0] > m0max) m0max = pts[i].m[0]; }\n      var m0span = m0max - m0min || 1;\n      for (i = 0; i < n; i++) s1[i] = clamp((pts[i].m[0] - m0min) / m0span, 0, 1);\n      return { score: score, s1: s1, d2: d2, mean: med, scale: scale };\n    }\n\n    function median(arr, n) {\n      var a = arr.slice(0, n).sort(function (x, y) { return x - y; });\n      var m = n >> 1;\n      return n % 2 ? a[m] : (a[m - 1] + a[m]) / 2;\n    }\n\n    function invert(m, n) {\n      var a = new Float64Array(m), aug = new Float64Array(n * n * 2);\n      var i, j, k;\n      for (i = 0; i < n * n; i++) aug[i] = m[i];\n      for (i = 0; i < n; i++) aug[i * 2 * n + n + i] = 1;\n      for (i = 0; i < n; i++) {\n        /* 选主元 */\n        var pivot = i;\n        for (k = i + 1; k < n; k++) if (Math.abs(aug[k * 2 * n + i]) > Math.abs(aug[pivot * 2 * n + i])) pivot = k;\n        if (Math.abs(aug[pivot * 2 * n + i]) < 1e-12) continue;\n        if (pivot !== i) {\n          for (j = 0; j < 2 * n; j++) { var t = aug[i * 2 * n + j]; aug[i * 2 * n + j] = aug[pivot * 2 * n + j]; aug[pivot * 2 * n + j] = t; }\n        }\n        var div = aug[i * 2 * n + i];\n        for (j = 0; j < 2 * n; j++) aug[i * 2 * n + j] /= div;\n        for (k = 0; k < n; k++) {\n          if (k === i) continue;\n          var f = aug[k * 2 * n + i];\n          if (Math.abs(f) < 1e-15) continue;\n          for (j = 0; j < 2 * n; j++) aug[k * 2 * n + j] -= f * aug[i * 2 * n + j];\n        }\n      }\n      for (i = 0; i < n; i++) for (j = 0; j < n; j++) a[i * n + j] = aug[i * 2 * n + n + j];\n      return a;\n    }\n\n    /* -----------------------------------------------------\n       屏 2 · DBSCAN 空间聚类\n       对异常分数高于 th 的点做密度聚类（eps 邻域 + minPts）。\n       返回 { labels: IntArray(按点), clusters: [..], noiseIds }\n       ----------------------------------------------------- */\n    function clusterAnomaly(pts, score, th, eps, minPts) {\n      var n = pts.length, i;\n      var labels = new Int32Array(n).fill(-1); /* -1 未访问 / -2 噪声 */\n      var clusters = [];\n      for (i = 0; i < n; i++) labels[i] = -1;\n      var visited = new Array(n).fill(0);\n      var cid = 0;\n      for (i = 0; i < n; i++) {\n        if (visited[i]) continue;\n        visited[i] = 1;\n        if (score[i] < th) continue; /* 非异常点，跳过 */\n        var neigh = regionQuery(pts, i, eps);\n        if (neigh.length < minPts) { labels[i] = -2; continue; }\n        /* 新建簇 */\n        labels[i] = cid;\n        var seed = neigh.slice();\n        while (seed.length) {\n          var q = seed.pop();\n          if (!visited[q]) {\n            visited[q] = 1;\n            if (score[q] >= th) {\n              var qN = regionQuery(pts, q, eps);\n              if (qN.length >= minPts) seed = seed.concat(qN);\n            }\n          }\n          if (labels[q] === -1 || labels[q] === -2) labels[q] = cid;\n        }\n        cid++;\n      }\n      /* 整理簇：每个簇的点集合 + 中心 */\n      var byC = {};\n      for (i = 0; i < n; i++) {\n        var c = labels[i];\n        if (c >= 0) { (byC[c] = byC[c] || []).push(i); }\n      }\n      var clustersOut = [];\n      var keys = Object.keys(byC).map(Number).sort(function (a, b) { return a - b; });\n      for (var k = 0; k < keys.length; k++) {\n        var ids = byC[keys[k]];\n        var cx = 0, cy = 0;\n        for (i = 0; i < ids.length; i++) { cx += pts[ids[i]].x; cy += pts[ids[i]].y; }\n        clustersOut.push({ id: keys[k], ids: ids, cx: cx / ids.length, cy: cy / ids.length, size: ids.length });\n      }\n      return { labels: labels, clusters: clustersOut, nCluster: clustersOut.length, noiseCount: countNoise(labels, n) };\n    }\n\n    function countNoise(labels, n) { var c = 0; for (var i = 0; i < n; i++) if (labels[i] === -2) c++; return c; }\n\n    function regionQuery(pts, idx, eps) {\n      var out = [];\n      for (var i = 0; i < pts.length; i++) {\n        var dx = pts[i].x - pts[idx].x, dy = pts[i].y - pts[idx].y;\n        if (dx * dx + dy * dy <= eps * eps) out.push(i);\n      }\n      return out;\n    }\n\n    /* -----------------------------------------------------\n       屏 3 · 靶区概率图（地统计插值 + 分层）\n       用 IDW 把异常分数插值成连续概率场（grid G×G）。\n       再按 pTh 分层：高/中/低潜力区。\n       返回 { grid: FloatArray(G*G), layer: IntArray, G }\n       ----------------------------------------------------- */\n    function interpProb(pts, score, G, power, radius) {\n      var n = pts.length;\n      var grid = new Float64Array(G * G);\n      var minX = 0, maxX = 60, minY = 0, maxY = 48;\n      var stepX = (maxX - minX) / G, stepY = (maxY - minY) / G;\n      var gx, gy, i;\n      for (gy = 0; gy < G; gy++) {\n        for (gx = 0; gx < G; gx++) {\n          var px = minX + (gx + 0.5) * stepX, py = minY + (gy + 0.5) * stepY;\n          var wsum = 0, ssum = 0;\n          for (i = 0; i < n; i++) {\n            var dx = pts[i].x - px, dy = pts[i].y - py;\n            var d2 = dx * dx + dy * dy;\n            if (d2 < 1e-9) { ssum = score[i] * 1e9; wsum = 1e9; continue; }\n            var w = 1 / Math.pow(Math.sqrt(d2), power);\n            wsum += w; ssum += w * score[i];\n          }\n          grid[gy * G + gx] = wsum > 0 ? ssum / wsum : 0;\n        }\n      }\n      /* 归一化到 0~1 */\n      var mx = 0, mn = 1;\n      for (i = 0; i < G * G; i++) { if (grid[i] > mx) mx = grid[i]; if (grid[i] < mn) mn = grid[i]; }\n      var span = mx - mn || 1;\n      for (i = 0; i < G * G; i++) grid[i] = clamp((grid[i] - mn) / span, 0, 1);\n      return { grid: grid, G: G };\n    }\n\n    /* 分层：高(2)/中(1)/低(0) 潜力 */\n    function layerProb(grid, G, pHi, pMid) {\n      var layer = new Int32Array(G * G);\n      for (var i = 0; i < G * G; i++) {\n        layer[i] = grid[i] >= pHi ? 2 : (grid[i] >= pMid ? 1 : 0);\n      }\n      return layer;\n    }\n\n    /* 与已知靶区重合度：算法高潜力区（grid >= pTh）与 target 点的重合比例 */\n    function targetOverlap(pts, grid, G, pTh) {\n      var hit = 0, tot = 0, i;\n      var stepX = 60 / G, stepY = 48 / G;\n      for (i = 0; i < pts.length; i++) {\n        if (!pts[i].target) continue;\n        tot++;\n        var gx = Math.floor(pts[i].x / stepX), gy = Math.floor(pts[i].y / stepY);\n        if (gx < 0) gx = 0; if (gx >= G) gx = G - 1;\n        if (gy < 0) gy = 0; if (gy >= G) gy = G - 1;\n        if (grid[gy * G + gx] >= pTh) hit++;\n      }\n      return tot ? hit / tot : 0;\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32,\n      METRIC_NAMES: METRIC_NAMES, METRIC_COLORS: METRIC_COLORS,\n      genPoints: genPoints, detectAnomaly: detectAnomaly,\n      clusterAnomaly: clusterAnomaly, interpProb: interpProb, layerProb: layerProb,\n      targetOverlap: targetOverlap\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  /* 全局 UI 状态 */\n  var detState = { pts: 300, K: 4, noise: 0.35, th: 0.6 };\n  var clsState = { eps: 2.2, minPts: 4, th: 0.55 };\n  var probState = { pTh: 0.55, power: 2, pHi: 0.75, pMid: 0.45 };\n\n  /* 数据缓存：一次生成，多屏复用 */\n  var geo = M.genPoints(detState.pts, detState.K, detState.noise, 20261103);\n  var pts = geo.pts;\n  var NM = geo.nMetric;\n  var det = M.detectAnomaly(pts, NM, detState.noise);\n\n  /* 桥接：给算法解剖动画用同一份真代码 */\n  global.RemoteBridge = {\n    M: M,\n    genPoints: M.genPoints, detectAnomaly: M.detectAnomaly,\n    clusterAnomaly: M.clusterAnomaly, interpProb: M.interpProb, layerProb: M.layerProb,\n    targetOverlap: M.targetOverlap,\n    live: function () {\n      return { pts: detState.pts, K: detState.K, noise: detState.noise, th: detState.th, eps: clsState.eps, minPts: clsState.minPts, pTh: probState.pTh, power: probState.power, pHi: probState.pHi, pMid: probState.pMid };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n  var PA = '#b26a39', PB = '#41699b', PC = '#2f7d6b', PNOISE = '#9ba3a9', PBG = '#e8e4d8';\n  function hexA(hex, a) {\n    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);\n    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';\n  }\n\n  /* =====================================================\n     屏 1 · 多指标异常检测\n     ===================================================== */\n  var W1 = 60, H1 = 48, S1 = 8; /* SVG 480×384 */\n\n  function renderDet() {\n    var n = pts.length, i;\n    /* 单指标 vs 多指标：异常分数排序后的 top 判定 */\n    var topN = Math.max(10, Math.floor(n * 0.1));\n    /* 单指标：取第 0 项 top */\n    var singleIdx = [];\n    for (i = 0; i < n; i++) singleIdx.push(i);\n    singleIdx.sort(function (a, b) { return det.s1[b] - det.s1[a]; });\n    var singleTop = {};\n    for (i = 0; i < topN; i++) singleTop[singleIdx[i]] = 1;\n    var multiIdx = singleIdx.slice().sort(function (a, b) { return det.score[b] - det.score[a]; });\n    var multiTop = {};\n    for (i = 0; i < topN; i++) multiTop[multiIdx[i]] = 1;\n\n    var s1 = '', s2 = '';\n    for (i = 0; i < n; i++) {\n      var px = pts[i].x * S1, py = pts[i].y * S1;\n      var colSingle = singleTop[i] ? PA : (det.s1[i] > detState.th ? '#c98a5c' : PNOISE);\n      var colMulti = multiTop[i] ? PB : (det.score[i] > detState.th ? '#7fa3c9' : PNOISE);\n      s1 += '<circle cx=\"' + px.toFixed(1) + '\" cy=\"' + py.toFixed(1) + '\" r=\"3.4\" fill=\"' + colSingle + '\"/>';\n      s2 += '<circle cx=\"' + px.toFixed(1) + '\" cy=\"' + py.toFixed(1) + '\" r=\"3.4\" fill=\"' + colMulti + '\"/>';\n    }\n    $('detSingle').innerHTML = s1;\n    $('detMulti').innerHTML = s2;\n\n    /* 读数 */\n    var singleHit = 0, multiHit = 0, targetCnt = 0;\n    for (i = 0; i < n; i++) { if (pts[i].target) { targetCnt++; if (singleTop[i]) singleHit++; if (multiTop[i]) multiHit++; } }\n    $('roDetSingle').innerHTML = (singleHit / Math.max(1, targetCnt) * 100).toFixed(0) + '%';\n    $('roDetMulti').innerHTML = (multiHit / Math.max(1, targetCnt) * 100).toFixed(0) + '%';\n    $('roDetDelta').innerHTML = '+ ' + (Math.max(0, multiHit - singleHit) / Math.max(1, targetCnt) * 100).toFixed(0) + '%';\n    /* 假异常：top 里非 target 的点 */\n    var singleFA = 0, multiFA = 0;\n    for (i = 0; i < n; i++) {\n      if (singleTop[i] && !pts[i].target) singleFA++;\n      if (multiTop[i] && !pts[i].target) multiFA++;\n    }\n    $('roDetFA').innerHTML = multiFA + ' / ' + singleFA;\n  }\n\n  /* =====================================================\n     屏 2 · 空间聚类成靶区\n     ===================================================== */\n  var S2 = 8;\n\n  function renderCls() {\n    var n = pts.length, i;\n    var cl = M.clusterAnomaly(pts, det.score, clsState.th, clsState.eps, clsState.minPts);\n    var CLUS_COL = [PB, PC, PA, '#7a4e9b', '#b98f5a', '#5a8a9b', '#41699b', '#2f7d6b'];\n    var s = '';\n    /* 背景点 */\n    for (i = 0; i < n; i++) {\n      var px = pts[i].x * S2, py = pts[i].y * S2;\n      var col;\n      if (cl.labels[i] === -2) col = '#d7a27c'; /* 噪声 */\n      else if (cl.labels[i] >= 0) col = CLUS_COL[cl.labels[i] % CLUS_COL.length];\n      else col = det.score[i] > clsState.th ? '#7fa3c9' : PNOISE;\n      s += '<circle cx=\"' + px.toFixed(1) + '\" cy=\"' + py.toFixed(1) + '\" r=\"3.2\" fill=\"' + col + '\"/>';\n    }\n    /* 簇边界椭圆 */\n    for (i = 0; i < cl.clusters.length; i++) {\n      var c = cl.clusters[i];\n      var rx = 0, ry = 0, j;\n      for (j = 0; j < c.ids.length; j++) {\n        var dx = pts[c.ids[j]].x - c.cx, dy = pts[c.ids[j]].y - c.cy;\n        if (Math.abs(dx) > rx) rx = Math.abs(dx);\n        if (Math.abs(dy) > ry) ry = Math.abs(dy);\n      }\n      s += '<ellipse cx=\"' + (c.cx * S2).toFixed(1) + '\" cy=\"' + (c.cy * S2).toFixed(1) + '\" rx=\"' + (rx * S2 + 6).toFixed(1) + '\" ry=\"' + (ry * S2 + 6).toFixed(1) + '\" fill=\"' + hexA(CLUS_COL[c.id % CLUS_COL.length], 0.14) + '\" stroke=\"' + CLUS_COL[c.id % CLUS_COL.length] + '\" stroke-width=\"1.2\" stroke-dasharray=\"4 3\"/>';\n    }\n    $('clsChart').innerHTML = s;\n    $('roClsClusters').innerHTML = cl.nCluster + ' 个';\n    $('roClsNoise').innerHTML = cl.noiseCount + ' 点';\n    $('roClsSize').innerHTML = (cl.clusters.length ? Math.round(cl.clusters.reduce(function (a, c) { return a + c.size; }, 0) / cl.clusters.length) : 0) + ' 点/靶区';\n  }\n\n  /* =====================================================\n     屏 3 · 靶区概率图 + 重合度\n     ===================================================== */\n  var G3 = 30, S3 = 15; /* SVG 450×360 */\n  function probColor(p) {\n    if (p >= probState.pHi) return PC;\n    if (p >= probState.pMid) return '#7fc0a9';\n    if (p >= probState.pTh) return '#d7e8de';\n    return '#eef1f1';\n  }\n\n  function renderProb() {\n    var interp = M.interpProb(pts, det.score, G3, probState.power, 12);\n    var layer = M.layerProb(interp.grid, G3, probState.pHi, probState.pMid);\n    var s = '';\n    var gx, gy;\n    for (gy = 0; gy < G3; gy++) {\n      for (gx = 0; gx < G3; gx++) {\n        s += '<rect x=\"' + (gx * S3) + '\" y=\"' + (gy * S3) + '\" width=\"' + S3 + '\" height=\"' + S3 + '\" fill=\"' + probColor(interp.grid[gy * G3 + gx]) + '\"/>';\n      }\n    }\n    /* 叠加已知靶区边界 */\n    for (var i = 0; i < pts.length; i++) {\n      if (pts[i].target) {\n        s += '<circle cx=\"' + (pts[i].x * S3) + '\" cy=\"' + (pts[i].y * S3) + '\" r=\"3.4\" fill=\"none\" stroke=\"#7a4e9b\" stroke-width=\"1.3\"/>';\n      }\n    }\n    $('probChart').innerHTML = s;\n    var overlap = M.targetOverlap(pts, interp.grid, G3, probState.pTh);\n    $('roOverlap').innerHTML = (overlap * 100).toFixed(0) + '%';\n    /* 高/中/低潜力区占比 */\n    var hi = 0, mid = 0, lo = 0;\n    for (i = 0; i < G3 * G3; i++) { if (layer[i] === 2) hi++; else if (layer[i] === 1) mid++; else lo++; }\n    $('roProbHi').innerHTML = (hi / (G3 * G3) * 100).toFixed(0) + '%';\n    $('roProbMid').innerHTML = (mid / (G3 * G3) * 100).toFixed(0) + '%';\n    $('roProbLo').innerHTML = (lo / (G3 * G3) * 100).toFixed(0) + '%';\n  }\n\n  /* 重建数据（改噪声时复用） */\n  function regen() {\n    geo = M.genPoints(detState.pts, detState.K, detState.noise, 20261103);\n    pts = geo.pts;\n    NM = geo.nMetric;\n    det = M.detectAnomaly(pts, NM, detState.noise);\n  }\n\n  /* =====================================================\n     bind + 启动\n     ===================================================== */\n  function bind() {\n    /* 屏 1 */\n    var sel = $('selMetric');\n    if (sel) {\n      var opts = '';\n      for (var i = 0; i < M.METRIC_NAMES.length; i++) opts += '<option value=\"' + i + '\">' + M.METRIC_NAMES[i] + '<\/option>';\n      sel.innerHTML = opts;\n      sel.addEventListener('change', function () { detState.metric = +this.value; renderDet(); });\n    }\n    var pNoise = $('pNoise');\n    if (pNoise) pNoise.addEventListener('input', function () { detState.noise = +this.value; regen(); $('roNoise').textContent = num(this.value, 2); renderDet(); renderCls(); renderProb(); });\n    var pTh = $('pTh');\n    if (pTh) pTh.addEventListener('input', function () { detState.th = +this.value; $('roTh').textContent = num(this.value, 2); renderDet(); });\n    /* 屏 2 */\n    var pEps = $('pEps');\n    if (pEps) pEps.addEventListener('input', function () { clsState.eps = +this.value; $('roEps').textContent = num(this.value, 1); renderCls(); });\n    var pMin = $('pMinPts');\n    if (pMin) pMin.addEventListener('input', function () { clsState.minPts = +this.value; $('roMinPts').textContent = this.value; renderCls(); });\n    var pTh2 = $('pTh2');\n    if (pTh2) pTh2.addEventListener('input', function () { clsState.th = +this.value; $('roTh2').textContent = num(this.value, 2); renderCls(); });\n    /* 屏 3 */\n    var pPTh = $('pPTh');\n    if (pPTh) pPTh.addEventListener('input', function () { probState.pTh = +this.value; $('roPTh').textContent = num(this.value, 2); renderProb(); });\n    var pPow = $('pPow');\n    if (pPow) pPow.addEventListener('input', function () { probState.power = +this.value; $('roPow').textContent = num(this.value, 1); renderProb(); });\n    var pPHi = $('pPHi');\n    if (pPHi) pPHi.addEventListener('input', function () { probState.pHi = +this.value; $('roPHi').textContent = num(this.value, 2); renderProb(); });\n  }\n\n  /* 启动 */\n  renderDet();\n  renderCls();\n  renderProb();\n  bind();\n\n  /* 按段落上报控件到父页（嵌入主站时） */\n  function setupDrawer() {\n    if (typeof window === 'undefined' || window.parent === window) return; /* 独立模式无需上报 */\n    function post(ev, payload) { try { window.parent.postMessage({ t: 'demo', c: 'drawer', ev: ev, payload: payload }, '*'); } catch (e) {} }\n    post('init', {\n      blocks: [\n        { sec: 1, title: '多指标异常检测', controls: [\n          { key: 'metric', label: '单指标', type: 'select', value: '0' },\n          { key: 'noise', label: '背景噪声', type: 'range', min: 0.1, max: 1, step: 0.05, value: detState.noise },\n          { key: 'th', label: '异常阈值', type: 'range', min: 0.3, max: 0.9, step: 0.05, value: detState.th }\n        ]},\n        { sec: 2, title: '空间聚类成靶区', controls: [\n          { key: 'eps', label: '邻域半径 eps', type: 'range', min: 1, max: 4, step: 0.2, value: clsState.eps },\n          { key: 'minPts', label: '最小点数', type: 'range', min: 2, max: 8, step: 1, value: clsState.minPts },\n          { key: 'th2', label: '异常阈值', type: 'range', min: 0.3, max: 0.9, step: 0.05, value: clsState.th }\n        ]},\n        { sec: 3, title: '靶区概率图', controls: [\n          { key: 'pTh', label: '圈定阈值', type: 'range', min: 0.3, max: 0.9, step: 0.05, value: probState.pTh },\n          { key: 'power', label: '插值幂', type: 'range', min: 1, max: 4, step: 0.5, value: probState.power },\n          { key: 'pHi', label: '高潜力线', type: 'range', min: 0.6, max: 0.95, step: 0.05, value: probState.pHi }\n        ]}\n      ]\n    });\n    window.addEventListener('message', function (e) {\n      if (!e.data || e.data.t !== 'demo' || e.data.c !== 'drawer') return;\n      var key = e.data.key, val = e.data.value;\n      if (key === 'metric') { detState.metric = +val; renderDet(); }\n      else if (key === 'noise') { detState.noise = +val; regen(); renderDet(); renderCls(); renderProb(); }\n      else if (key === 'th') { detState.th = +val; renderDet(); }\n      else if (key === 'eps') { clsState.eps = +val; renderCls(); }\n      else if (key === 'minPts') { clsState.minPts = +val; renderCls(); }\n      else if (key === 'th2') { clsState.th = +val; renderCls(); }\n      else if (key === 'pTh') { probState.pTh = +val; renderProb(); }\n      else if (key === 'power') { probState.power = +val; renderProb(); }\n      else if (key === 'pHi') { probState.pHi = +val; renderProb(); }\n    });\n  }\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   油气地球化学异常识别 · 算法解剖（多指标检测 + 空间聚类）\n   ---------------------------------------------------------\n   把「采样点 → 靶区概率图」拆成 6 步，每一步都跑真代码：\n\n     ① 采样数据整理    坐标 + 多指标，剔缺测、标准化\n     ② 多指标异常检测  鲁棒 z-score 协同度 → 每点异常分数\n     ③ 异常分数分布   单指标 vs 多指标联合\n     ④ 空间聚类成靶区  DBSCAN 把邻近高异常点聚成靶区\n     ⑤ 靶区概率图     IDW 插值成连续概率场 + 分层\n     ⑥ 靶区验证与回写  与已知靶区重合度 → 人工复核\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function ease(t) { return t * t * (3 - 2 * t); }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  /* 面板底部小结框 */\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* 采样点散点：把 pts 数组画成圆点 */\n  function ptMap(pts, score, W, H, S, x0, y0, opts) {\n    opts = opts || {};\n    var r = opts.r || 2.4;\n    var s = '';\n    for (var i = 0; i < pts.length; i++) {\n      var p = pts[i];\n      var px = x0 + p.x * S, py = y0 + p.y * S;\n      var col = opts.color ? opts.color(p, i) : (p.target ? '#7a4e9b' : '#9ba3a9');\n      s += G.circle(px, py, r, { fill: col, op: opts.op || 1 });\n    }\n    return s;\n  }\n\n  /* 靶区边界：簇外接椭圆（用 path 近似） */\n  function clusterEllipse(pts, cluster, S, x0, y0, col) {\n    var rx = 0, ry = 0;\n    for (var j = 0; j < cluster.ids.length; j++) {\n      var p = pts[cluster.ids[j]];\n      if (Math.abs(p.x - cluster.cx) > rx) rx = Math.abs(p.x - cluster.cx);\n      if (Math.abs(p.y - cluster.cy) > ry) ry = Math.abs(p.y - cluster.cy);\n    }\n    var cx = x0 + cluster.cx * S, cy = y0 + cluster.cy * S, a = (rx + 2) * S, b = (ry + 2) * S;\n    var d = 'M' + (cx - a) + ' ' + cy + 'a' + a + ',' + b + ' 0 1,0 ' + (2 * a) + ',0a' + a + ',' + b + ' 0 1,0 ' + (-2 * a) + ',0';\n    return G.path(d, { fill: hexA(col, 0.14), stroke: col, sw: 1.2, dash: '4 3' });\n  }\n\n  function hexA(hex, a) {\n    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);\n    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.pts, L.K, L.noise, L.th, L.eps, L.minPts, L.pTh, L.power, L.pHi, L.pMid].join(',');\n    if (cache.key === key) return cache;\n    var geo = M.genPoints(L.pts, L.K, L.noise, 20261103);\n    var pts = geo.pts;\n    var det = M.detectAnomaly(pts, geo.nMetric, L.noise);\n    var cl = M.clusterAnomaly(pts, det.score, L.th, L.eps, L.minPts);\n    var ip = M.interpProb(pts, det.score, 30, L.power, 12);\n    var layer = M.layerProb(ip.grid, 30, L.pHi, L.pMid);\n    var ov = M.targetOverlap(pts, ip.grid, 30, L.pTh);\n    cache = { key: key, L: L, geo: geo, pts: pts, det: det, cl: cl, ip: ip, layer: layer, ov: ov };\n    return cache;\n  }\n\n  var W = 60, H = 48, S = 8; /* 采样区 60×48 → SVG 480×384 */\n\n  /* =========================================================\n     ① 采样数据整理\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), pts = c.pts, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 采样点', '坐标 + 多指标', C.blue);\n    s += G.panel(1, '② 清洗', '剔缺测 / 异常值', C.clay);\n    s += G.panel(2, '③ 标准化', '去量纲，指标等权', C.jade);\n\n    var x0 = 30, y0 = 130;\n    /* 全采样点（背景灰，异常区紫） */\n    s += ptMap(pts, null, W, H, S, x0, y0, { color: function (p) { return p.target ? '#b58cc4' : '#c3c8cb'; } });\n    s += G.txt(x0, y0 - 12, '化探采样点 · ' + pts.length + ' 点 · ' + L.K + ' 个已知异常区（紫）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 130, 192, '采样的现实',\n      ['· 单区块 300—3000 点',\n       '· 每点 5—10 项化验指标',\n       '· 坐标决定空间聚类能否成靶区',\n       '',\n       '缺测、量纲不统一会',\n       '让异常检测失真。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '第一步把「点 × 多指标 + 坐标」整理成干净表——异常检测的输入', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '采样点', v: pts.length }, { k: '指标', v: L.geo ? L.geo.nMetric : 6 + ' 项' }, { k: '异常区', v: L.K + ' 个' }], note: '化探数据是一张「点 × 多指标 + 坐标」的表。缺测、量纲不统一会让异常检测失真，所以先清洗、再标准化。' };\n  }\n\n  /* =========================================================\n     ② 多指标异常检测\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), pts = c.pts, det = c.det, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 鲁棒中心化', '中位数代替均值', C.blue);\n    s += G.panel(1, '② 鲁棒缩放', 'MAD 代替标准差', C.jade);\n    s += G.panel(2, '③ 协同度', '超标项数 + 平均偏离', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 异常分数散点：分数高 → 深红 */\n    s += ptMap(pts, null, W, H, S, x0, y0, { color: function (p, i) {\n      var sc = det.score[i];\n      var g = Math.round(150 + 100 * (1 - sc));\n      return 'rgb(205,' + g + ',' + Math.round(140 + 60 * (1 - sc)) + ')';\n    } });\n    s += G.txt(x0, y0 - 12, '多指标异常分数（协同度判据）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 130, 192, '为什么中位数 + MAD',\n      ['· 异常点占 1/3，会拉偏均值',\n       '→ 中位数不受污染',\n       '· MAD × 1.4826 ≈ 标准差',\n       '→ 尺度估计也鲁棒',\n       '',\n       '协同度：z 超阈值 2.0 的指标数',\n       '→ 只抓「多项一起偏离」。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '单指标会被污染点骗，多指标协同度要求「多项一起偏离」才判异常', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '异常点', v: L.pts }, { k: '判据', v: '协同度' }, { k: '阈值', v: 'z>2.0' }], note: '多指标异常检测用鲁棒统计（中位数 + MAD）估计背景，再用「协同度」判据——只有多项指标一起偏离才算异常，单指标被污染点干扰的问题就解决了。' };\n  }\n\n  /* =========================================================\n     ③ 异常分数分布：单指标 vs 多指标\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), pts = c.pts, det = c.det, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 单指标', '只看吸附烃', C.clay);\n    s += G.panel(1, '② 多指标', '协同度联合', C.jade);\n    s += G.panel(2, '③ 对比', '漏检 vs 假异常', C.blue);\n\n    var x0 = 30, y0 = 130;\n    /* 双散点：左单指标（top 红），右多指标（top 红） */\n    var topN = Math.max(10, Math.floor(pts.length * 0.1));\n    var si = [], i;\n    for (i = 0; i < pts.length; i++) si.push(i);\n    var singleTop = new Set(si.slice().sort(function (a, b) { return det.s1[b] - det.s1[a]; }).slice(0, topN));\n    var multiTop = new Set(si.slice().sort(function (a, b) { return det.score[b] - det.score[a]; }).slice(0, topN));\n\n    /* 左：单指标 */\n    s += ptMap(pts, null, W, H, S, x0, y0, { color: function (p, i) { return singleTop.has(i) ? '#b26a39' : (det.s1[i] > L.th ? '#d7a27c' : '#c3c8cb'); } });\n    s += G.txt(x0 + W * S / 2, y0 - 12, '单指标 top' + topN + '（吸附烃）', { size: 9.5, fill: C.ink2, weight: 700, anchor: 'middle' });\n    /* 右：多指标 */\n    var x1 = 330;\n    s += ptMap(pts, null, W, H, S, x1, y0, { color: function (p, i) { return multiTop.has(i) ? '#41699b' : (det.score[i] > L.th ? '#8fb0d0' : '#c3c8cb'); } });\n    s += G.txt(x1 + W * S / 2, y0 - 12, '多指标 top' + topN + '（协同度）', { size: 9.5, fill: C.ink2, weight: 700, anchor: 'middle' });\n\n    s += footBox(30, 570, y0 + 196, 44, null,\n      ['多指标把「组合异常」抓得更全、假异常更少 · 污染点（单项爆高）被协同度压住'], 'clay');\n\n    s += G.txt(30, y0 + 252, '对比读数见实验 1：多指标命中率更高、假异常为 0', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '单指标', v: '污染易干扰' }, { k: '多指标', v: '协同更准' }, { k: '假异常', v: '多指标更低' }], note: '同样是抓 top 异常，单指标被地表污染的单项高值点带偏，多指标协同度只认「多项一起偏高」，组合异常抓得又全又准。' };\n  }\n\n  /* =========================================================\n     ④ 空间聚类成靶区\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), pts = c.pts, cl = c.cl, det = c.det, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 高异常点', '协同度 > 阈值', C.clay);\n    s += G.panel(1, '② DBSCAN', '密度相连成簇', C.blue);\n    s += G.panel(2, '③ 靶区', '剔除孤立噪声', C.jade);\n\n    var x0 = 30, y0 = 130;\n    var CLUS_COL = ['#41699b', '#2f7d6b', '#b26a39', '#7a4e9b', '#b98f5a', '#5a8a9b'];\n    /* 背景 + 异常点着色 + 簇边界 */\n    s += ptMap(pts, null, W, H, S, x0, y0, { color: function (p, i) {\n      var lb = cl.labels[i];\n      if (lb === -2) return '#d7a27c';\n      if (lb >= 0) return CLUS_COL[lb % CLUS_COL.length];\n      return det.score[i] > L.th ? '#8fb0d0' : '#c3c8cb';\n    } });\n    for (var ci = 0; ci < cl.clusters.length; ci++) {\n      s += clusterEllipse(pts, cl.clusters[ci], S, x0, y0, CLUS_COL[cl.clusters[ci].id % CLUS_COL.length]);\n    }\n    s += G.txt(x0, y0 - 12, 'DBSCAN 聚类 · ' + cl.nCluster + ' 个靶区 · 噪声 ' + cl.noiseCount + ' 点', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 130, 192, '为什么用空间聚类',\n      ['· 异常点可能离散，未必成片',\n       '· DBSCAN：密度相连的点聚成簇',\n       '· 孤立高异常点被判为噪声剔除',\n       '',\n       'eps / minPts 是杠杆：',\n       '太小靶区过碎，太大连成一片。'], 'blue');\n\n    s += G.txt(x0, y0 + 208, '空间邻近 + 高异常 → 成靶区；孤立假异常 → 剔除', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '靶区', v: cl.nCluster }, { k: '噪声点', v: cl.noiseCount }, { k: 'eps', v: f(L.eps, 1) }], note: '异常检测给出的是离散点，空间聚类把它们聚成可解释的靶区，同时把孤立的假异常剔除——这是从「点」到「区块」的关键一步。' };\n  }\n\n  /* =========================================================\n     ⑤ 靶区概率图\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), ip = c.ip, layer = c.layer, L = c.L;\n    var s = '';\n    s += G.panel(0, '① IDW 插值', '离散点 → 连续场', C.blue);\n    s += G.panel(1, '② 概率场', '每格一个概率', C.jade);\n    s += G.panel(2, '③ 分层', '高 / 中 / 低潜力', C.clay);\n\n    var x0 = 30, y0 = 130, Gg = 30, Sg = 14;\n    function pcol(p) {\n      if (p >= L.pHi) return '#2f7d6b';\n      if (p >= L.pMid) return '#7fc0a9';\n      if (p >= L.pTh) return '#d7e8de';\n      return '#eef1f1';\n    }\n    for (var gy = 0; gy < Gg; gy++) {\n      for (var gx = 0; gx < Gg; gx++) {\n        s += G.rect(x0 + gx * Sg, y0 + gy * Sg, Sg, Sg, { fill: pcol(ip.grid[gy * Gg + gx]), op: 1 });\n      }\n    }\n    s += G.txt(x0, y0 - 12, '靶区概率图 · 高潜力 ' + f(L.pHi, 2) + ' / 中 ' + f(L.pMid, 2) + ' / 圈定 ' + f(L.pTh, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 130, 192, '概率图怎么读',\n      ['· 离散异常点插值成连续概率场',\n       '· 绿色 = 高潜力（优先布井）',\n       '· 浅绿 = 中潜力（跟踪）',\n       '· 白 = 低潜力（暂不考虑）',\n       '',\n       '插值幂 power 越大，场越陡；',\n       '太大 → 孤立斑块，太小 → 过平滑。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '从「逐点对比」变成「看概率图」——哪片更可能有油气一目了然', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '高潜力', v: countLayer(layer, 2, Gg) + '%' }, { k: '中潜力', v: countLayer(layer, 1, Gg) + '%' }, { k: '低潜力', v: countLayer(layer, 0, Gg) + '%' }], note: '概率图把离散的异常分数平滑成连续场并按高/中/低分层，解释员从「逐点对比」变成「看概率图」，圈靶更快也更客观。' };\n  }\n\n  function countLayer(layer, val, Gg) {\n    var cnt = 0;\n    for (var i = 0; i < Gg * Gg; i++) if (layer[i] === val) cnt++;\n    return Math.round(cnt / (Gg * Gg) * 100);\n  }\n\n  /* =========================================================\n     ⑥ 靶区验证与回写\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), pts = c.pts, ip = c.ip, layer = c.layer, L = c.L, ov = c.ov;\n    var s = '';\n    s += G.panel(0, '① 已知靶区', '专家圈定验证集', C.blue);\n    s += G.panel(1, '② 重合度', '概率图覆盖比', C.jade);\n    s += G.panel(2, '③ 人工复核', '新圈区域复核', C.clay);\n\n    var x0 = 30, y0 = 130, Gg = 30, Sg = 14;\n    function pcol(p) {\n      if (p >= L.pHi) return '#2f7d6b';\n      if (p >= L.pMid) return '#7fc0a9';\n      if (p >= L.pTh) return '#d7e8de';\n      return '#eef1f1';\n    }\n    for (var gy = 0; gy < Gg; gy++) {\n      for (var gx = 0; gx < Gg; gx++) {\n        s += G.rect(x0 + gx * Sg, y0 + gy * Sg, Sg, Sg, { fill: pcol(ip.grid[gy * Gg + gx]), op: 1 });\n      }\n    }\n    /* 已知靶区点（紫圈） */\n    for (var i = 0; i < pts.length; i++) {\n      if (pts[i].target) s += G.circle(x0 + pts[i].x * Sg, y0 + pts[i].y * Sg, 3.2, { fill: 'none', stroke: '#7a4e9b', sw: 1.3 });\n    }\n    s += G.txt(x0, y0 - 12, '靶区验证 · 与已知靶区重合度 ' + f(ov * 100, 0) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(330, 260, 130, 192, '怎么验收',\n      ['· 重合度 = 概率图高潜力区',\n       '  覆盖已知靶区的比例',\n       '· 必须空间分块交叉验证',\n       '  （自相关会让精度虚高）',\n       '',\n       '高潜力但不在已知靶区 → 复核',\n       '验证通过 → 回写为新靶区。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '重合度 ' + f(ov * 100, 0) + '% · 验证通过的回写为已知靶区，季度重估参数', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '重合度', v: f(ov * 100, 0) + '%' }, { k: '验证', v: '分块交叉' }, { k: '回写', v: '季度' }], note: '最后用已知靶区验证算法可信度，并对算法新圈出的高潜力区做人工复核——验证通过的回写为已知靶区，让靶区库越滚越大、圈靶越来越稳。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：油气地球化学异常识别<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 地质勘察 / 地球化学异常识别<\/span>\n  <h1>从「逐点判读 · 经验圈靶」到「多指标联合 · 靶区概率图」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂多指标异常检测、Q2 空间聚类成靶区、Q3 输出靶区概率图。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 靶区圈定全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「采样 → 黑盒 → 出图」，而是<b>逐段展开<\/b>：采样整理 → 多指标检测 → 分数分布 → 空间聚类 → 概率图 → 验证回写，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「采样点 → 靶区概率图」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改采样点数、背景噪声、聚类参数和概率阈值，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（异常分数图、靶区、概率图）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>detectAnomaly / clusterAnomaly / interpProb<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步用「中位数 + MAD + 协同度」说明多指标联合如何顶住污染点；<b>②<\/b> 第 4 步把 DBSCAN 聚类过程与孤立点剔除并排放，看得见「为什么空间聚类能剔假异常」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 多指标异常检测 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">单指标阈值会被地表污染点骗；多指标协同度只认「多项一起偏高」<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 2<\/span>\n    <h2>多指标异常检测：把「组合异常」从污染里捞出来<\/h2>\n    <p class=\"leadline\">左看单指标、右看多指标，拖异常阈值与背景噪声，看谁命中的异常点多、假异常少。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"detCtl\">\n    <div class=\"sl\">\n      <label>背景噪声<output id=\"outNoise\">0.35<\/output><\/label>\n      <input type=\"range\" id=\"pNoise\" min=\"0.1\" max=\"1\" step=\"0.05\" value=\"0.35\">\n    <\/div>\n    <div class=\"sl\">\n      <label>异常阈值<output id=\"outTh\">0.60<\/output><\/label>\n      <input type=\"range\" id=\"pTh\" min=\"0.3\" max=\"0.9\" step=\"0.05\" value=\"0.6\">\n    <\/div>\n  <\/div>\n  <div class=\"fg\">\n    <div><svg id=\"detSingle\" viewBox=\"0 0 480 384\" role=\"img\" aria-label=\"单指标异常点\"><\/svg><div class=\"cap\">单指标（吸附烃）top 异常<\/div><\/div>\n    <div><svg id=\"detMulti\" viewBox=\"0 0 480 384\" role=\"img\" aria-label=\"多指标异常点\"><\/svg><div class=\"cap\">多指标（协同度）top 异常<\/div><\/div>\n  <\/div>\n  <div class=\"rrow ro4\">\n    <div class=\"ro\"><span class=\"k\">单指标命中<\/span><b id=\"roDetSingle\" class=\"warn\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">多指标命中<\/span><b id=\"roDetMulti\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">提升<\/span><b id=\"roDetDelta\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">假异常 多/单<\/span><b id=\"roDetFA\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"detTip\">橙色 = 单指标判为异常的 top 点，蓝色 = 多指标判为异常的 top 点，紫圈 = 已知异常区。多指标协同度只认「多项一起偏高」，把单指标被污染点带偏的假异常压到 0。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 空间聚类成靶区 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>DBSCAN 密度聚类<\/b> 把空间邻近的高异常点聚成靶区、剔除孤立假异常<span class=\"qa-algo\">优化方法 · 空间聚类<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>空间聚类：把高异常点聚成一块块「靶区」<\/h2>\n    <p class=\"leadline\">异常检测给出的是离散点。拖邻域半径 eps 与最小点数，看异常点怎么聚成靶区、孤立噪声怎么被剔除。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"clsCtl\">\n    <div class=\"sl\">\n      <label>邻域半径 eps<output id=\"outEps\">2.2<\/output><\/label>\n      <input type=\"range\" id=\"pEps\" min=\"1\" max=\"4\" step=\"0.2\" value=\"2.2\">\n    <\/div>\n    <div class=\"sl\">\n      <label>最小点数<output id=\"outMinPts\">4<\/output><\/label>\n      <input type=\"range\" id=\"pMinPts\" min=\"2\" max=\"8\" step=\"1\" value=\"4\">\n    <\/div>\n    <div class=\"sl\">\n      <label>异常阈值<output id=\"outTh2\">0.55<\/output><\/label>\n      <input type=\"range\" id=\"pTh2\" min=\"0.3\" max=\"0.9\" step=\"0.05\" value=\"0.55\">\n    <\/div>\n  <\/div>\n  <svg id=\"clsChart\" viewBox=\"0 0 480 384\" role=\"img\" aria-label=\"空间聚类结果\"><\/svg>\n  <div class=\"rrow ro3\">\n    <div class=\"ro\"><span class=\"k\">靶区数<\/span><b id=\"roClsClusters\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">噪声点<\/span><b id=\"roClsNoise\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">平均规模<\/span><b id=\"roClsSize\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"clsTip\">同色椭圆 = 一个靶区，棕点 = 被判为噪声的孤立假异常。eps 太小靶区过碎，太大连成一片；最小点数越大越难成簇。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 靶区概率图 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">离散异常分数 → IDW 插值 → 连续概率场 → 高 / 中 / 低潜力分层<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5<\/span>\n    <h2>靶区概率图：哪片更可能有油气，一眼看出<\/h2>\n    <p class=\"leadline\">把离散点平滑成概率图，按阈值分层。紫圈 = 已知靶区，看算法圈出的高潜力区能不能盖住它们。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"probCtl\">\n    <div class=\"sl\">\n      <label>圈定阈值<output id=\"outPTh\">0.55<\/output><\/label>\n      <input type=\"range\" id=\"pPTh\" min=\"0.3\" max=\"0.9\" step=\"0.05\" value=\"0.55\">\n    <\/div>\n    <div class=\"sl\">\n      <label>插值幂<output id=\"outPow\">2.0<\/output><\/label>\n      <input type=\"range\" id=\"pPow\" min=\"1\" max=\"4\" step=\"0.5\" value=\"2\">\n    <\/div>\n    <div class=\"sl\">\n      <label>高潜力线<output id=\"outPHi\">0.75<\/output><\/label>\n      <input type=\"range\" id=\"pPHi\" min=\"0.6\" max=\"0.95\" step=\"0.05\" value=\"0.75\">\n    <\/div>\n  <\/div>\n  <svg id=\"probChart\" viewBox=\"0 0 450 360\" role=\"img\" aria-label=\"靶区概率图\"><\/svg>\n  <div class=\"rrow ro4\">\n    <div class=\"ro\"><span class=\"k\">靶区重合度<\/span><b id=\"roOverlap\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">高潜力区<\/span><b id=\"roProbHi\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">中潜力区<\/span><b id=\"roProbMid\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">低潜力区<\/span><b id=\"roProbLo\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"probTip\">绿色 = 高潜力区，浅绿 = 中潜力，白色 = 低潜力。重合度 = 概率图高潜力区覆盖已知靶区的比例。插值幂越大场越陡、越易出现孤立斑块。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>鲁棒 z-score 协同度，多指标联合判异常。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>DBSCAN 密度聚类，异常点聚成靶区、剔噪声。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>IDW 插值 + 分层，输出靶区概率图。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：化探采样点由「背景 + 组合异常区 + 单项污染点」合成，已知靶区仅供验证对比；异常检测、空间聚类与概率图均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：采样点怎么一步步变成靶区概率图',\n    stages: [\n      { name: '采样整理', tag: '坐标 + 多指标', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '异常检测', tag: '鲁棒协同度', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: '分数分布', tag: '单 vs 多指标', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '空间聚类', tag: 'DBSCAN', dur: 4600, draw: function (t, g) { return F.stage4(t); } },\n      { name: '概率图', tag: 'IDW 插值分层', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '验证回写', tag: '重合度 + 复核', dur: 4400, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的化探采样点演示多指标异常检测、空间聚类与靶区概率图。","height":600};
  var META = {"id":"g2-geochem-anomaly","sceneId":"g2","title":"油气地球化学异常识别：多指标联合检测与靶区圈定"};
  var handle = null;
  var DEF = {"id":"g2-geochem-anomaly","sceneId":"g2","title":"油气地球化学异常识别：多指标联合检测与靶区圈定","methods":["opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"采样点×多指标","desc":"单区块 300—3000 点，5—10 项化验值"},{"label":"标注成本","value":"低","desc":"无需逐点标注，3—5 个已知靶区验证"},{"label":"可见收益","value":"快速圈靶","desc":"从逐点对比到概率图，靶区圈定更客观"},{"label":"难度","value":"中","desc":"样本量小 + 空间自相关强，需空间分块验证"}],"lede":"油气藏中的油气会沿微裂缝向上渗漏，在地表土壤里留下化学痕迹——土壤吸附烃、酸解烃、ΔC 等化探指标测量的正是这些「油气微渗漏」。一个区块布设数百到数千个采样点，需多指标联合判读才能圈出有利靶区。智能方法把「单指标阈值 + 经验判读」升级为「多指标异常检测 + 空间聚类」：先识别组合异常，再圈出靶区概率图，替代人工逐点对比。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>化探采样在地表按网格或剖面布点，化验出吸附烃、酸解烃、ΔC 等多指标数值——这些指标是<b>油气微渗漏<\/b>在地表留下的化学痕迹，异常点往往指示地下油气聚集的线索。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>单指标阈值法脆弱<\/b>——受地表污染、地形与季节影响大，一个指标单独看噪声多、假异常多<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>多指标联合判读依赖经验<\/b>——什么组合算异常、异常边界在哪，不同人圈出的靶区差异大<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>异常与背景边界模糊<\/b>——空间上异常是渐变的，阈值切分主观性强<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"单指标阈值法的脆弱\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">单指标阈值法：噪声多 · 经验强 · 边界主观<\/text><rect x=\"20\" y=\"36\" width=\"286\" height=\"180\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"163\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">单指标（吸附烃）散点<\/text><line x1=\"40\" y1=\"190\" x2=\"292\" y2=\"190\" stroke=\"#efece1\" stroke-width=\"1\"/><rect x=\"20\" y=\"36\" width=\"4\" height=\"180\" rx=\"2\" fill=\"#41699b\"/><text x=\"30\" y=\"52\" font-size=\"8.5\" fill=\"#41699b\">指标值<\/text><text x=\"30\" y=\"198\" font-size=\"8.5\" fill=\"#79828a\">采样点 →<\/text><line x1=\"40\" y1=\"70\" x2=\"292\" y2=\"70\" stroke=\"#b26a39\" stroke-width=\"2\" stroke-dasharray=\"6 4\"/><text x=\"292\" y=\"63\" text-anchor=\"end\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"600\">阈值<\/text><circle cx=\"80\" cy=\"180\" r=\"4\" fill=\"#2f7d6b\"/><circle cx=\"120\" cy=\"172\" r=\"4\" fill=\"#2f7d6b\"/><circle cx=\"160\" cy=\"178\" r=\"4\" fill=\"#2f7d6b\"/><circle cx=\"120\" cy=\"120\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"200\" cy=\"60\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"150\" cy=\"50\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"240\" cy=\"58\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"260\" cy=\"130\" r=\"4\" fill=\"#9ba3a9\"/><circle cx=\"100\" cy=\"150\" r=\"4\" fill=\"#9ba3a9\"/><text x=\"40\" y=\"225\" font-size=\"8.5\" fill=\"#8a6b52\">· 地表污染/地形/季节让单指标噪声大<\/text><text x=\"40\" y=\"240\" font-size=\"8.5\" fill=\"#8a6b52\">· 哪些是异常、边界在哪，靠经验<\/text><rect x=\"318\" y=\"36\" width=\"282\" height=\"180\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"459\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">多人圈靶，差异大<\/text><circle cx=\"400\" cy=\"150\" r=\"36\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/><circle cx=\"400\" cy=\"150\" r=\"22\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><circle cx=\"400\" cy=\"150\" r=\"46\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"1.4\" stroke-dasharray=\"2 3\"/><circle cx=\"410\" cy=\"120\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"390\" cy=\"180\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"430\" cy=\"140\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"420\" cy=\"175\" r=\"4\" fill=\"#b26a39\"/><circle cx=\"540\" cy=\"130\" r=\"4\" fill=\"#9ba3a9\"/><circle cx=\"560\" cy=\"180\" r=\"4\" fill=\"#9ba3a9\"/><circle cx=\"500\" cy=\"170\" r=\"4\" fill=\"#9ba3a9\"/><text x=\"380\" y=\"120\" font-size=\"8\" fill=\"#b26a39\">A 圈<\/text><text x=\"438\" y=\"205\" font-size=\"8\" fill=\"#2f7d6b\">B 圈<\/text><text x=\"336\" y=\"225\" font-size=\"8.5\" fill=\"#8a6b52\">同一批数据，不同人圈出的靶区<\/text><text x=\"336\" y=\"240\" font-size=\"8.5\" fill=\"#8a6b52\">范围、边界各不相同<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「单指标阈值 + 经验判读」换成<b>「多指标异常检测 + 空间聚类」<\/b>：算法把每个采样点的高维指标压缩成一个<b>异常分数<\/b>，再结合空间位置把高异常点聚成<b>靶区<\/b>，输出概率图，解释员只负责验证靶区。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>多指标异常检测<\/b>——对吸附烃、酸解烃、ΔC 等多项做标准化 + 多维异常检测（马氏距离 / 孤立森林 / 鲁棒协方差），把「多个指标一起偏高」的组合异常揪出来<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>空间聚类<\/b>——用空间聚类 / 密度聚类（DBSCAN）把空间上邻近的高异常点聚成靶区，剔除孤立假异常<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>靶区概率图<\/b>——地统计插值把离散点平滑成概率场，输出「哪片区域更可能有油气」的图<\/span><\/div><\/div><p>落地形态：靶区圈定从「逐点对比」变成「看概率图」，异常识别客观可复现，解释员把精力放在验证靶区而非逐点判读。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"多指标异常检测与空间聚类\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">多指标异常检测 → 空间聚类 → 靶区概率图<\/text><rect x=\"20\" y=\"40\" width=\"160\" height=\"160\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"100\" y=\"60\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">采样点 × 多指标<\/text><rect x=\"32\" y=\"70\" width=\"136\" height=\"54\" rx=\"4\" fill=\"#f1f1ee\"/><text x=\"100\" y=\"88\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">吸附烃 · 酸解烃 · ΔC<\/text><text x=\"100\" y=\"102\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">… 共 5—10 项<\/text><text x=\"100\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#9ba3a9\">单区块 300—3000 点<\/text><text x=\"100\" y=\"146\" text-anchor=\"middle\" font-size=\"8\" fill=\"#9ba3a9\">含空间坐标<\/text><path d=\"M184 120 L210 120\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"40\" width=\"170\" height=\"160\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"299\" y=\"60\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">多指标异常检测<\/text><text x=\"299\" y=\"80\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">马氏距离 / 孤立森林<\/text><text x=\"299\" y=\"96\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">鲁棒协方差<\/text><text x=\"299\" y=\"116\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">每点一个异常分数<\/text><text x=\"299\" y=\"136\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">「多指标一起偏高」的组合异常<\/text><text x=\"299\" y=\"152\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">不受单指标噪声干扰<\/text><path d=\"M388 120 L414 120\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"418\" y=\"40\" width=\"182\" height=\"160\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"509\" y=\"60\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">空间聚类 → 靶区<\/text><text x=\"509\" y=\"80\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">DBSCAN 密度聚类<\/text><text x=\"509\" y=\"96\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">邻近高异常点聚成靶区<\/text><text x=\"509\" y=\"116\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">剔除孤立假异常<\/text><text x=\"509\" y=\"136\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">地统计插值 → 概率图<\/text><text x=\"509\" y=\"152\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">输出「哪片更可能有油气」<\/text><rect x=\"20\" y=\"214\" width=\"580\" height=\"26\" rx=\"6\" fill=\"#e7eef9\"/><text x=\"310\" y=\"232\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">靶区圈定从「逐点对比」变「看概率图」——客观、可复现、可验证<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>化探采样点数据<\/b>：单区块 300—3000 点，含空间坐标（经纬度 / 网格位置）与 5—10 项化验指标（吸附烃、酸解烃、ΔC 等），是异常检测的主信号；<b>已知靶区<\/b>：3—5 个由地质专家圈定的靶区，作为验证集（非训练标签）；<b>地质与遥感背景图层<\/b>：与采样区同范围，辅助剔除地表污染造成的假异常。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">三类数据 + 关键现实<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">化探采样点数据<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">300—3000 点 · 5—10 项指标 + 坐标<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">异常检测的主信号<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">已知靶区（验证集）<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">3—5 个专家圈定靶区<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">只做验证，不做训练标签<\/text><rect x=\"20\" y=\"106\" width=\"582\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">地质与遥感背景图层<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">与采样区同范围 · 地表污染 / 地形 / 季节<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">辅助剔除假异常<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"310\" y=\"202\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">关键现实：样本量小 + 空间自相关强 → 必须按空间分块交叉验证，否则精度被高估<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>样本量小<\/b>——一个区块只有几百到几千点，模型容易过拟合<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>空间自相关<\/b>——邻近采样点指标相近，随机切分会让验证集「作弊」，精度被严重高估<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>地表污染假异常<\/b>——城镇、农田、河流附近指标异常但并非油气渗漏<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>多指标异常检测<\/b>（马氏距离 / 孤立森林）做基线；再加<b>空间聚类<\/b>剔孤立假异常；最后做<b>空间分块交叉验证<\/b>评估真实精度，结合地质背景剔除污染。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 样本量小<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">几百到几千点，易过拟合<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">多指标异常检测基线<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">马氏距离 / 孤立森林<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 空间自相关<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">随机切分让验证集作弊<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">空间分块交叉验证<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">按空间分块评估真实精度<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 地表污染假异常<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">城镇/农田/河流附近指标异常<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">空间聚类 + 背景剔除<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">DBSCAN + 地质背景图层<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">异常检测基线 → 空间聚类 → 空间分块验证 + 背景剔除污染<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个区块的化探靶区圈定改造","lead":["某勘探区块布设 1200 个化探采样点、化验 7 项指标（吸附烃、酸解烃、ΔC 等）。此前靠单指标阈值 + 专家判读圈靶，靶区主观、假异常多。目标：用多指标异常检测 + 空间聚类输出靶区概率图，与 4 个已知靶区的重合度显著提升。","注意第 3、4、5 步：异常检测、空间聚类、概率图是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["采样点","1200"],["化验指标","7 项"],["已知靶区","4 个"],["目标靶区","小时级"],["重合度","≥70%"],["假异常","降低一半"]],"steps":[{"name":"采样数据整理","role":"数据","do":"采样点坐标与化验指标对齐，剔除缺测、异常值；多指标做标准化（去量纲）。示范页屏 1 可切换指标、调噪声，看多指标联合与单指标的差异。","effect":"一张「点 × 多指标 + 坐标」的干净表，供异常检测使用。","trap":"缺测与量纲不统一会让马氏距离失真，指标间权重失衡。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">采样整理：对齐坐标 → 剔缺测 → 标准化<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">原始采样表<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">坐标 + 7 项指标<\/text><path d=\"M178 68 L202 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">剔缺测异常<\/text><text x=\"281\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">清洗噪声点<\/text><path d=\"M360 68 L384 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">标准化<\/text><text x=\"488\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">去量纲，指标等权<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：缺测/量纲不统一 → 马氏距离失真 → 指标权重失衡<\/text><\/svg>"},{"name":"多指标异常检测","role":"算法核心","do":"对标准化后的多指标做多维异常检测（马氏距离 / 孤立森林 / 鲁棒协方差），每个采样点得到一个异常分数；分数越高越可能是「多指标一起偏高」的组合异常。示范页屏 1 在浏览器里实时算异常分数并标注。","effect":"把「多指标一起偏高」的组合异常揪出来，不受单指标噪声干扰。","trap":"只用单指标阈值会漏掉组合异常，被地表污染的单个高值带偏。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">异常检测：多指标 → 马氏距离 → 异常分数<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">多指标向量<\/text><text x=\"89\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">7 维标准化值<\/text><path d=\"M158 68 L182 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"186\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"251\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">马氏距离<\/text><text x=\"251\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">含协方差<\/text><path d=\"M320 68 L344 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"348\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"413\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">异常分数<\/text><text x=\"413\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每点一个<\/text><path d=\"M482 68 L506 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"510\" y=\"42\" width=\"86\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"553\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">判异常<\/text><text x=\"553\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">> 阈值<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：单指标阈值漏掉组合异常，被污染单值带偏<\/text><\/svg>"},{"name":"空间聚类成靶区","role":"算法核心","do":"对异常分数高的采样点做空间密度聚类（DBSCAN），把空间上邻近的高异常点聚成靶区，剔除孤立假异常点。示范页屏 2 展示聚类过程与靶区边界。","effect":"邻近的高异常点聚成一个个靶区，孤立假异常被剔除。","trap":"DBSCAN 参数（eps/minPts）选不好，靶区要么过碎要么连成一片。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">空间聚类：高异常点 → DBSCAN → 靶区<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">异常点分布<\/text><circle cx=\"70\" cy=\"84\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"90\" cy=\"78\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"80\" cy=\"96\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"130\" cy=\"60\" r=\"5\" fill=\"#9ba3a9\"/><path d=\"M178 77 L202 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">DBSCAN 聚类<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">密度相连成簇<\/text><circle cx=\"240\" cy=\"70\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"260\" cy=\"66\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"250\" cy=\"86\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"290\" cy=\"96\" r=\"5\" fill=\"#9ba3a9\"/><path d=\"M360 77 L384 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"463\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">靶区 + 剔除<\/text><text x=\"463\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">孤立点剔除<\/text><circle cx=\"420\" cy=\"70\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"440\" cy=\"66\" r=\"5\" fill=\"#b26a39\"/><circle cx=\"430\" cy=\"86\" r=\"5\" fill=\"#b26a39\"/><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：eps/minPts 选不好 → 靶区过碎或连成一片<\/text><\/svg>"},{"name":"地统计插值成概率图","role":"工程环节","do":"用克吕金插值 / IDW 把离散的异常分数平滑成连续的靶区概率图；按概率阈值分层（高/中/低潜力区）。示范页屏 3 展示概率图与分层结果。","effect":"从离散点变成一张「哪片更可能有油气」的连续概率图，直观可读。","trap":"插值半径 / 变程选不好，概率图过平滑或出现孤立斑块。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">概率图：异常分数 → 地统计插值 → 分层<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">异常分数点<\/text><text x=\"89\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">离散采样点<\/text><path d=\"M158 68 L182 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"186\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"251\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">克吕金 / IDW<\/text><text x=\"251\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">空间平滑<\/text><path d=\"M320 68 L344 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"348\" y=\"42\" width=\"130\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"413\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">概率图<\/text><text x=\"413\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">连续概率场<\/text><path d=\"M482 68 L506 68\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"510\" y=\"42\" width=\"86\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"553\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">分层<\/text><text x=\"553\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高/中/低<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：插值变程选不好 → 概率图过平滑或孤立斑块<\/text><\/svg>"},{"name":"靶区验证与人工确认","role":"人工确认","do":"把概率图的高潜力区与 4 个已知靶区比对，算重合度；对高潜力但不在已知靶区的区域做地质复核。示范页屏 3 展示重合度与待复核区。","effect":"用已知靶区验证算法可信度，人只复核算法新圈出的区域。","trap":"不按空间分块验证，自相关让精度虚高，实际靶区重合度被高估。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">靶区验证：概率图 vs 已知靶区 → 重合度<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">已知靶区<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">4 个专家圈定<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">算法高潜力区<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">概率图圈出<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">重合度 + 复核<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高潜力不在已知靶区 → 复核<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不空间分块验证 → 自相关让精度虚高<\/text><\/svg>"},{"name":"回流与参数更新","role":"闭环","do":"验证通过的靶区回写为已知靶区，季度重估异常检测阈值与聚类参数；持续监控靶区重合度与假异常数。示范页屏 3 展示参数对结果的影响。","effect":"靶区库越滚越大，异常检测与聚类参数越用越准，圈靶更稳。","trap":"不回写验证结果，已知靶区永远只有 4 个，参数停在不达标状态。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">回流：验证靶区回写 → 季度重估参数<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">验证通过靶区<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">回写为已知靶区<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">季度重估参数<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">阈值 + eps/minPts<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">监控重合度<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">假异常持续下降<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不回写验证结果 → 已知靶区永远是 4 个<\/text><\/svg>"}],"metrics":{"title":"怎么算「圈靶圈对了」","html":"<p>核心看 <b>靶区重合度<\/b>：算法高潜力区与已知靶区的重合比例（越高越好），以及 <b>假异常数<\/b>（算法圈出但验证为非油气的靶区，越低越好）。<\/p><p>异常检测本身验收用 <b>检出率 / 误报率<\/b>；但必须<b>空间分块交叉验证<\/b>——按空间分块训练与测试，否则自相关让精度虚高。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='靶区圈定效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>某区块 1200 点 · 人工判读 vs 多指标异常检测 + 空间聚类<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>靶区重合度（对已知靶区）<\/text><rect x='60' y='70' width='70' height='64' fill='#d9b78e'/><text x='95' y='106' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>48%<\/text><text x='95' y='122' text-anchor='middle' font-size='8' fill='#8a6b52'>人工判读<\/text><rect x='180' y='38' width='70' height='96' fill='#2f7d6b'/><text x='215' y='74' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>78%<\/text><text x='215' y='90' text-anchor='middle' font-size='8' fill='#b9d8cb'>多指标+聚类<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>重合度更高且可复现<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>假异常数<\/text><rect x='340' y='72' width='90' height='62' fill='#d9b78e'/><text x='385' y='104' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>11<\/text><text x='385' y='120' text-anchor='middle' font-size='8' fill='#8a6b52'>人工判读<\/text><rect x='500' y='98' width='90' height='36' fill='#2f7d6b'/><text x='545' y='120' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>5<\/text><text x='545' y='136' text-anchor='middle' font-size='8' fill='#b9d8cb'>多指标+聚类<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>假异常降低一半<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 靶区重合度 × 假异常数 × 空间分块交叉验证 · 三项都要达标<\/text><\/svg><\/p>"},"fails":[{"name":"精度虚高","why":"空间自相关强，随机切分验证集让邻近点「作弊」，重合度被严重高估，实际圈靶不准。"},{"name":"假异常误报","why":"地表污染（城镇/农田/河流）导致指标异常但并非油气渗漏，算法把它们圈成靶区。"},{"name":"聚类参数敏感","why":"DBSCAN 的 eps/minPts 选不好，靶区要么过碎要么连成一片，与已知靶区对不上。"},{"name":"单指标带偏","why":"只用一个指标或指标权重失衡，被污染的单个高值带偏，组合异常反而漏掉。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的化探采样点演示多指标异常检测、空间聚类与靶区概率图。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
